{
  "article_id": "E2-010",
  "outcome": "Propose a readable bilingual article layout that preserves every supplied paragraph, its wording, order and qualifications.",
  "reader_need": "Read the account and compare languages without mistaking extraction furniture for reporting or losing the conditions attached to advice.",
  "decisions": [
    {
      "proposal": "Use two language columns on wide screens and complete language sections on narrow screens. Align corresponding passages by meaning, not paragraph number; allow unequal block heights.",
      "paragraph_evidence": [
        {
          "cn": ["p4"],
          "en": ["p4", "p6"],
          "observation": "The Chinese survey paragraph corresponds to English text split across two paragraphs."
        },
        {
          "cn": ["p14"],
          "en": ["p16"],
          "observation": "Both languages end with Davis's reframing and improved sleep; the English ending must remain visible despite its higher paragraph number."
        }
      ],
      "benefit": "Supports comparison while retaining each language's complete reading order and ending.",
      "cost": "Unequal passage lengths create whitespace in paired columns; narrow screens require scrolling between languages."
    },
    {
      "proposal": "Set English p5 in smaller, readable secondary type, retaining its exact text and position between p4 and p6. Keep p4 and p6 visually close without merging or rewriting them.",
      "paragraph_evidence": [
        {
          "cn": ["p4"],
          "en": ["p4", "p5", "p6"],
          "observation": "“[Continued on page A12.]” is extraction furniture with no Chinese counterpart and interrupts an English sentence."
        }
      ],
      "benefit": "Distinguishes the continuation notice from reporting while preserving the unmatched paragraph and sentence sequence.",
      "cost": "The retained notice still interrupts reading, and secondary type needs sufficient size and contrast."
    },
    {
      "proposal": "Use consistent body-text emphasis for statistics, anecdotes and advice; preserve paragraph breaks and keep conditions, attribution and quotations together without enlarged excerpts.",
      "paragraph_evidence": [
        {
          "cn": ["p4"],
          "en": ["p4", "p6"],
          "observation": "The prevalence claim is tied to an October FlexJobs survey of 2,100 people."
        },
        {
          "cn": ["p12", "p13"],
          "en": ["p14", "p15"],
          "observation": "Prewitt permits limited Sunday work conditionally, while Hakim recommends alternatives that avoid it."
        }
      ],
      "benefit": "Keeps evidence and qualifications attached to claims and gives differing recommendations comparable visual weight.",
      "cost": "Readers receive fewer visual shortcuts and must read the paragraphs to understand the distinctions."
    }
  ]
}
